CREATE OR REPLACE PACKAGE SETTLE.SETTLEMENT_PKG AS
  PROCEDURE CALC_PAYMENT(p_delivery_id NUMBER);
  PROCEDURE RUN_ALL;
END SETTLEMENT_PKG;
/
CREATE OR REPLACE PACKAGE BODY SETTLE.SETTLEMENT_PKG AS
  PROCEDURE CALC_PAYMENT(p_delivery_id NUMBER) IS
    v_price  NUMBER;
    v_amount NUMBER;
    v_grade  CHAR(1);
    v_moist  NUMBER;
  BEGIN
    SELECT q.GRADE, d.MOISTURE_PCT INTO v_grade, v_moist
      FROM HARVEST.DELIVERIES d JOIN HARVEST.QUALITY_TESTS q ON q.DELIVERY_ID = d.DELIVERY_ID
     WHERE d.DELIVERY_ID = p_delivery_id;
    SELECT PRICE_PER_T INTO v_price FROM SETTLE.PRICE_RULES WHERE GRADE = v_grade AND ROWNUM = 1;
    IF v_grade = 'A' AND v_moist < 14 THEN
      v_price := v_price * 1.10;
    ELSIF v_moist > 18 THEN
      v_price := v_price * 0.85;
    END IF;
    IF v_grade = 'D' THEN
      UPDATE HARVEST.DELIVERIES SET STATUS = 'REJECTED' WHERE DELIVERY_ID = p_delivery_id;
      RETURN;
    END IF;
    INSERT INTO SETTLE.PAYMENTS (PAYMENT_ID, DELIVERY_ID, AMOUNT) VALUES (SETTLE.PAYMENT_SEQ.NEXTVAL, p_delivery_id, v_amount);
    LOG_AUDIT('PAYMENT', p_delivery_id);
  END CALC_PAYMENT;

  PROCEDURE RUN_ALL IS
    TYPE t_ids IS TABLE OF NUMBER;
    v_ids t_ids;
    v_resp UTL_HTTP.RESP;
  BEGIN
    SELECT DELIVERY_ID BULK COLLECT INTO v_ids FROM HARVEST.DELIVERIES WHERE STATUS = 'TESTED';
    FOR i IN 1 .. v_ids.COUNT LOOP
      CALC_PAYMENT(v_ids(i));
    END LOOP;
    EXECUTE IMMEDIATE 'ANALYZE TABLE SETTLE.PAYMENTS COMPUTE STATISTICS';
    v_resp := UTL_HTTP.GET_RESPONSE(UTL_HTTP.BEGIN_REQUEST('https://bank.example/batch'));
  END RUN_ALL;
END SETTLEMENT_PKG;
/
CREATE OR REPLACE PROCEDURE SETTLE.LOG_AUDIT(p_action VARCHAR2, p_ref NUMBER) IS
  PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN
  INSERT INTO SETTLE.AUDIT_LOG (LOGGED_AT, ACTION, DETAIL) VALUES (SYSTIMESTAMP, p_action, TO_CHAR(p_ref));
  COMMIT;
END LOG_AUDIT;
/
CREATE OR REPLACE PROCEDURE HARVEST.CLOSE_SEASON(p_year NUMBER) IS
BEGIN
  UPDATE HARVEST.DELIVERIES SET STATUS = 'PAID' WHERE EXTRACT(YEAR FROM DELIVERED_ON) = p_year AND STATUS = 'TESTED';
  DELETE FROM SETTLE.PAYMENTS WHERE PAID_ON IS NULL AND AMOUNT = 0;
  FOR r IN (SELECT GROWER_ID FROM HARVEST.GROWERS CONNECT BY PRIOR GROWER_ID = GROWER_ID) LOOP
    NULL;
  END LOOP;
END CLOSE_SEASON;
/
CREATE OR REPLACE TRIGGER HARVEST.TRG_DELIVERIES_BI
BEFORE INSERT ON HARVEST.DELIVERIES
FOR EACH ROW
BEGIN
  IF :NEW.WEIGHT_KG > 40000 THEN
    RAISE_APPLICATION_ERROR(-20001, 'A delivery cannot exceed 40 tonnes');
  END IF;
  :NEW.STATUS := 'NEW';
END;
/
